from pathlib import Path
p=Path('/home/ubuntu/kentankclient/src/App.tsx')
s=p.read_text(); start=s.index('function Admin('); end=s.index('function ProductEditor(', start)
replacement=r'''function Admin({ products, setProducts, setView }: { products: Product[]; setProducts: (products: Product[]) => void; setView: (view: View) => void }) {
  const [tab, setTab] = useState('Overview'); const [token, setToken] = useState(localStorage.getItem('kentank_admin_token') || ''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [loginBusy, setLoginBusy] = useState(false); const [loginMessage, setLoginMessage] = useState(''); const [authed, setAuthed] = useState(Boolean(token)); const [inquiries, setInquiries] = useState<any[]>([]); const [adminBanners, setAdminBanners] = useState<Banner[]>([]); const [banner, setBanner] = useState({ eyebrow: 'Kentank', title: '', body: '', image_url: '', cta_label: 'Explore the collection', cta_url: '/catalogue', placement: 'home_hero', active: true, sort_order: 0 }); const [bannerBusy, setBannerBusy] = useState(false); const [bannerMessage, setBannerMessage] = useState('');
  const loadAdmin = async (path: string) => { const response = await fetch(`${API}${path}`, { headers: { Authorization: `Bearer ${token}` } }); if (!response.ok) throw new Error('Admin authentication failed'); return response.json() };
  const login = async (e: FormEvent) => { e.preventDefault(); setLoginBusy(true); setLoginMessage(''); try { const response = await fetch(`${API}/api/auth/admin/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password }) }); if (!response.ok) { setLoginMessage('Sign in failed. Please check your email and password.'); return } const result = await response.json(); localStorage.setItem('kentank_admin_token', result.access_token); setToken(result.access_token); setAuthed(true) } catch { setLoginMessage('The admin service is temporarily unavailable. Please try again.') } finally { setLoginBusy(false) } };
  useEffect(() => { if (!authed) return; loadAdmin('/api/admin/products').then(setProducts).catch(() => setAuthed(false)); loadAdmin('/api/admin/inquiries').then(setInquiries).catch(() => undefined); loadAdmin('/api/admin/banners').then(setAdminBanners).catch(() => undefined) }, [authed]);
  const updateBanner = (key: string, value: any) => setBanner(prev => ({ ...prev, [key]: value }));
  const uploadBannerImage = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; setBannerBusy(true); setBannerMessage(''); try { const data = new FormData(); data.append('file', file); data.append('upload_preset', 'task_images'); const response = await fetch('https://api.cloudinary.com/v1_1/doste1wr0/image/upload', { method: 'POST', body: data }); if (!response.ok) throw new Error('Banner image upload failed'); const result = await response.json(); updateBanner('image_url', result.secure_url); setBannerMessage('Banner image uploaded.'); } catch (error) { setBannerMessage(error instanceof Error ? error.message : 'Banner image upload failed.'); } finally { setBannerBusy(false); event.target.value = '' } };
  const saveBanner = async (event: FormEvent) => { event.preventDefault(); setBannerBusy(true); setBannerMessage(''); try { const response = await fetch(`${API}/api/admin/banners`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ ...banner, sort_order: Number(banner.sort_order) }) }); if (!response.ok) throw new Error('Could not save banner'); const saved = await response.json(); setAdminBanners([...adminBanners, saved]); setBanner({ eyebrow: 'Kentank', title: '', body: '', image_url: '', cta_label: 'Explore the collection', cta_url: '/catalogue', placement: 'home_hero', active: true, sort_order: adminBanners.length + 1 }); setBannerMessage('Banner saved successfully.'); } catch (error) { setBannerMessage(error instanceof Error ? error.message : 'Could not save banner.'); } finally { setBannerBusy(false) } };
  const changeBanner = async (item: Banner, changes: Partial<Banner>) => { const response = await fetch(`${API}/api/admin/banners/${item.id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ ...item, ...changes }) }); if (response.ok) setAdminBanners(adminBanners.map(current => current.id === item.id ? { ...current, ...changes } : current)); };
  const deleteBanner = async (item: Banner) => { if (!confirm('Delete this banner?')) return; const response = await fetch(`${API}/api/admin/banners/${item.id}`, { method: 'DELETE', headers: { Authorization: `Bearer ${token}` } }); if (response.ok) setAdminBanners(adminBanners.filter(current => current.id !== item.id)); };
  if (!authed) return <div className="admin-login"><Logo /><h1>Admin workspace</h1><p>Sign in with your administrator account.</p><form onSubmit={login}><label>Email address<input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="admin@example.com" required /></label><label>Password<input type="password" value={password} onChange={e => setPassword(e.target.value)} required /></label>{loginMessage && <div className="error-note">{loginMessage}</div>}<button className="primary-button" disabled={loginBusy}>{loginBusy ? <Spinner label="Signing in…" /> : <>Enter workspace <span>↗</span></>}</button></form><button className="text-link" onClick={() => setView('home')}>← Return to store</button></div>;
  return <div className="admin-shell"><aside className="admin-sidebar"><button className="logo-button" onClick={() => setView('home')}><Logo compact /></button><p className="admin-label">Workspace</p>{['Overview', 'Products', 'Banners', 'Enquiries'].map(item => <button key={item} className={`admin-nav ${tab === item ? 'active' : ''}`} onClick={() => setTab(item)}>{item}</button>)}<div className="admin-sidebar-bottom"><span className="status-dot" />Store is live<button onClick={() => setView('home')}>← Back to store</button><button onClick={() => { localStorage.removeItem('kentank_admin_token'); setToken(''); setAuthed(false) }}>Sign out</button></div></aside><main className="admin-main"><div className="admin-top"><div><p className="eyebrow">Kentank / {tab}</p><h1>{tab === 'Overview' ? 'Good morning.' : tab}</h1></div><div className="admin-user">EK <span>Admin</span></div></div>{tab === 'Overview' && <><div className="admin-metrics"><div><span>Published products</span><strong>{products.filter(p => p.published).length}</strong><small>Live in catalogue</small></div><div><span>Open enquiries</span><strong>{inquiries.filter(i => i.status === 'new').length}</strong><small>Awaiting reply</small></div><div><span>Homepage banners</span><strong>{adminBanners.filter(b => b.active).length}</strong><small>Currently active</small></div></div><section className="admin-panel feature-panel"><p className="eyebrow">Store control</p><h2>Manage what customers see.</h2><p>Products, imagery, and homepage advertising are controlled from this workspace.</p><button className="primary-button" onClick={() => setTab('Banners')}>Manage banners <span>→</span></button></section></>}{tab === 'Products' && <section className="admin-panel admin-table"><div className="panel-heading"><div><p className="eyebrow">Catalogue manager</p><h2>Products</h2></div><button className="primary-button" onClick={() => setTab('New product')}>+ Add product</button></div>{products.map(p => <div className="admin-product-row" key={p.id}><span className="tank-mini" style={{ '--tank-colour': p.colour } as React.CSSProperties} />{p.image_url && <img className="admin-row-image" src={p.image_url} alt="" />}<div><strong>{p.name}</strong><small>{capacity(p.capacity_litres)} · {p.category}</small></div><span>{money(Number(p.discounted_price ?? p.price))}</span><b>{p.published ? 'Published' : 'Draft'}</b><button onClick={() => setTab(`Edit:${p.id}`)}>Edit →</button></div>)}</section>}{tab === 'Banners' && <section className="admin-panel banner-manager"><div className="panel-heading"><div><p className="eyebrow">Advertising manager</p><h2>Homepage banners</h2></div></div><form className="product-editor" onSubmit={saveBanner}><label>Eyebrow<input value={banner.eyebrow} onChange={e => updateBanner('eyebrow', e.target.value)} /></label><label>Banner title<input required value={banner.title} onChange={e => updateBanner('title', e.target.value)} /></label><label className="full-field">Description<textarea required rows={3} value={banner.body} onChange={e => updateBanner('body', e.target.value)} /></label><label>CTA label<input value={banner.cta_label} onChange={e => updateBanner('cta_label', e.target.value)} /></label><label>CTA URL<input value={banner.cta_url} onChange={e => updateBanner('cta_url', e.target.value)} /></label><label>Placement<select value={banner.placement} onChange={e => updateBanner('placement', e.target.value)}><option value="home_hero">Homepage hero</option><option value="home_mid">Homepage mid-page</option><option value="catalogue">Catalogue</option></select></label><label>Sort order<input type="number" min="0" value={banner.sort_order} onChange={e => updateBanner('sort_order', e.target.value)} /></label><label className="check-field"><input type="checkbox" checked={banner.active} onChange={e => updateBanner('active', e.target.checked)} /> Active</label><div className="banner-upload full-field">{banner.image_url ? <img src={banner.image_url} alt="Banner preview" /> : <div className="empty-state">No banner image selected.</div>}<label className="secondary-button">{bannerBusy ? 'Uploading…' : 'Upload banner image'}<input type="file" accept="image/*" onChange={uploadBannerImage} disabled={bannerBusy} hidden /></label></div>{bannerMessage && <div className="success-note full-field">{bannerMessage}</div>}<div className="editor-actions full-field"><button className="primary-button" disabled={bannerBusy}>{bannerBusy ? <Spinner label="Saving…" /> : <>Save banner <span>↗</span></>}</button></div></form><div className="banner-list">{adminBanners.map(item => <article className="banner-admin-card" key={item.id}>{item.image_url && <img src={item.image_url} alt={item.title} />}<div><p className="eyebrow">{item.placement}</p><h3>{item.title}</h3><p>{item.body}</p><div className="banner-card-actions"><label><input type="checkbox" checked={item.active} onChange={e => changeBanner(item, { active: e.target.checked })} /> Active</label><button onClick={() => changeBanner(item, { sort_order: Math.max(0, item.sort_order - 1) })}>Move up</button><button onClick={() => changeBanner(item, { sort_order: item.sort_order + 1 })}>Move down</button><button className="danger-link" onClick={() => deleteBanner(item)}>Delete</button></div></div></article>)}</div></section>}{tab === 'Enquiries' && <section className="admin-panel"><div className="panel-heading"><div><p className="eyebrow">Customer conversations</p><h2>Enquiries</h2></div></div>{inquiries.map(i => <div className="content-editor-row" key={i.id}><span><strong>{i.customer_name}</strong><small>{i.message}</small></span><span>{i.status}</span></div>)}{!inquiries.length && <div className="empty-state">No enquiries yet.</div>}</section>}{(tab === 'New product' || tab.startsWith('Edit:')) && <ProductEditor product={tab.startsWith('Edit:') ? products.find(p => p.id === Number(tab.split(':')[1])) : undefined} token={token} api={API} onSaved={(next) => { setProducts(products.some(p => p.id === next.id) ? products.map(p => p.id === next.id ? next : p) : [...products, next]); setTab('Products') }} onDeleted={(id) => { setProducts(products.filter(p => p.id !== id)); setTab('Products') }} />}</main></div>
}'''
p.write_text(s[:start]+replacement+'\n'+s[end:])
